import{computed,onMounted,ref}from'vue';import NxAlert from'../../components/ui/NxAlert.vue';import NxBadge from'../../components/ui/NxBadge.vue';import NxButton from'../../components/ui/NxButton.vue';import NxCard from'../../components/ui/NxCard.vue';import NxPageHeader from'../../components/ui/NxPageHeader.vue';import NxTableShell from'../../components/ui/NxTableShell.vue';import{getJson}from'../../lib/api';
type Trend={snapshot_id:number;collected_at:string;overall_status:string;memory_percent:number|null;disk_percent:number|null;load_1m:number|null};type Data=Record<string,any>&{infrastructure:{latest:any;history:{trend:Trend[];events:any[]};delivery:{pending:number;delivered:number;failed:number;last_delivered_at?:string}}};const data=ref<Data|null>(null),loading=ref(false),error=ref(''),refreshed=ref<Date|null>(null);const latest=computed(()=>data.value?.infrastructure?.latest||{}),system=computed(()=>latest.value.system||{}),services=computed(()=>Object.entries(latest.value.services||{})),events=computed(()=>data.value?.infrastructure?.history?.events||[]),trend=computed(()=>data.value?.infrastructure?.history?.trend||[]),healthyServices=computed(()=>services.value.filter(([,v])=>['HEALTHY','ONLINE'].includes(String((v as any).status))).length);const tone=(s?:string)=>s==='HEALTHY'||s==='ONLINE'?'success':s==='DEGRADED'?'warning':s==='CRITICAL'||s==='OFFLINE'?'danger':'neutral';const num=(v:any)=>Number(v||0).toLocaleString();const percent=(v:any)=>v==null?'—':Number(v).toFixed(1)+'%';const fmt=(v?:string)=>v?new Date(v.replace(' ','T')).toLocaleString('en-PH'):'Never';const uptime=(v:any)=>{const s=Number(v||0),d=Math.floor(s/86400),h=Math.floor(s%86400/3600);return d?`${d}d ${h}h`:`${h}h`;};const points=(key:'memory_percent'|'disk_percent')=>{const values=trend.value.slice(-48);if(!values.length)return'';return values.map((x,i)=>`${values.length===1?0:i/(values.length-1)*100},${100-Math.max(0,Math.min(100,Number(x[key]||0)))}`).join(' ')};const stale=computed(()=>{const at=Date.parse(String(latest.value.collected_at||''));return !at||Date.now()-at>Number(latest.value.stale_after_seconds||180)*1000;});async function load(){loading.value=true;error.value='';try{data.value=await getJson<Data>('/api/v1/dashboard/stats');refreshed.value=new Date();}catch(e){error.value=e instanceof Error?e.message:'Unable to load dashboard.';}finally{loading.value=false;}}onMounted(()=>void load());
</script>
