<template><div class="space-y-4 overflow-x-hidden pb-8 text-[var(--nx-text)]"><NxPageHeader eyebrow="ISP-in-a-Box operations" title="Infrastructure and service overview" description="Live platform health, host capacity, network services, subscribers, and provisioning state."><template #actions><NxButton variant="secondary" :disabled="loading" @click="load">{{loading?'Refreshing…':'Refresh'}}</NxButton></template></NxPageHeader><NxAlert v-if="error" tone="danger">{{error}}</NxAlert><NxAlert v-if="stale&&data" tone="warning">The latest infrastructure snapshot is stale. Confirm that the monitoring scheduler is running.</NxAlert><div v-if="data" class="space-y-4">
