<section class="grid gap-4 xl:grid-cols-[1.35fr_.65fr]"><NxCard title="Host capacity" description="Actual Linux host utilization from the scheduled collector."><div class="grid gap-5 sm:grid-cols-3"><div><div class="flex justify-between text-sm"><b>Memory</b><span>{{percent(system.memory_percent)}}</span></div><div class="mt-2 h-2 rounded bg-[var(--nx-surface-muted)]"><div class="h-full rounded bg-blue-500" :style="{width:Math.min(100,Number(system.memory_percent||0))+'%'}"></div></div></div><div><div class="flex justify-between text-sm"><b>Disk</b><span>{{percent(system.disk_percent)}}</span></div><div class="mt-2 h-2 rounded bg-[var(--nx-surface-muted)]"><div class="h-full rounded bg-emerald-500" :style="{width:Math.min(100,Number(system.disk_percent||0))+'%'}"></div></div></div><div><div class="flex justify-between text-sm"><b>Load / uptime</b><span>{{Number(system.load_1m||0).toFixed(2)}}</span></div><p class="mt-2 text-sm text-[var(--nx-text-muted)]">{{uptime(system.uptime_seconds)}} uptime</p></div></div><div class="mt-6 grid gap-4 sm:grid-cols-2"><div><p class="mb-2 text-xs font-bold uppercase text-[var(--nx-text-muted)]">Memory trend</p><svg viewBox="0 0 100 100" preserveAspectRatio="none" class="h-24 w-full rounded-lg bg-[var(--nx-surface-muted)] p-2" aria-label="Memory utilization trend"><polyline :points="points('memory_percent')" fill="none" stroke="#3b82f6" stroke-width="2" vector-effect="non-scaling-stroke"/></svg></div><div><p class="mb-2 text-xs font-bold uppercase text-[var(--nx-text-muted)]">Disk trend</p><svg viewBox="0 0 100 100" preserveAspectRatio="none" class="h-24 w-full rounded-lg bg-[var(--nx-surface-muted)] p-2" aria-label="Disk utilization trend"><polyline :points="points('disk_percent')" fill="none" stroke="#10b981" stroke-width="2" vector-effect="non-scaling-stroke"/></svg></div></div></NxCard><NxCard title="Monitoring delivery" description="Local readiness for the future HQ dashboard."><div class="space-y-3"><div class="flex justify-be