<section class="grid gap-4 xl:grid-cols-2"><NxCard title="Operational metrics" description="Current verified records from subscriber, network, billing, and provisioning modules."><div class="grid gap-2 sm:grid-cols-2"><div v-for="item in [{l:'Active services',v:data.active_services},{l:'Suspended services',v:data.suspended_services},{l:'Online ONTs',v:data.online_onts},{l:'Offline ONTs',v:data.offline_onts},{l:'Available NAP ports',v:data.available_nap_ports},{l:'Used NAP ports',v:data.used_nap_ports},{l:'Unpaid subscribers',v:data.unpaid_subscribers},{l:'Provisioning success',v:data.provisioning_success}]" :key="item.l" class="flex justify-between rounded-lg bg-[var(--nx-surface-muted)] px-3 py-3 text-sm"><span>{{item.l}}</span><b>{{num(item.v)}}</b></div></div></NxCard><NxCard title="Infrastructure incidents" description="Real status transitions recorded during the last 24 hours."><NxTableShell min-width="540px"><thead class="bg-[var(--nx-surface-muted)] text-xs uppercase"><tr><th class="px-3 py-2">Started</th><th class="px-3 py-2">Transition</th><th class="px-3 py-2">Recovery</th></tr></thead><tbody><tr v-if="!events.length"><td colspan="3" class="p-8 text-center text-sm text-[var(--nx-text-muted)]">No infrastructure incidents in the last 24 hours.</td></tr><tr v-for="event in events" :key="event.id"><td class="whitespace-nowrap px-3 py-2 text-sm">{{fmt(event.started_at)}}</td><td class="px-3 py-2 text-sm"><b>{{event.previous_status||'UNKNOWN'}}</b> → <b>{{event.current_status}}</b></td><td class="whitespace-nowrap px-3 py-2 text-sm">{{event.recovered_at?fmt(event.recovered_at):'Active'}}</td></tr></tbody></NxTableShell></NxCard></section><p class="text-right text-xs text-[var(--nx-text-muted)]">Dashboard refreshed {{refreshed?.toLocaleTimeString('en-PH')}}</p></div><div v-else-if="loading" class="rounded-lg border border-[var(--nx-border)] bg-[var(--nx-surface)] p-12 text-center text-sm text-[var(--nx-text-muted)]">Loading ISP-in-a-Box metrics…</div></div></temp